import {esc,fmt} from '../state.js';import {socket} from '../net.js';
const cases=[['contract','standard','Finanzierten Liefervertrag ausprobieren'],['cooperation','standard','Gemeinsamen Lieferauftrag ausprobieren'],['production','standard','Wasserwerk: Standardbetrieb'],['production','efficient','Wasserwerk: Rohstoffe sparen, mehr Energie'],['exploration','survey','Erkundung: Quelle kartografieren'],['exploration','salvage','Erkundung: endlichen Fund bergen'],['diplomacy','standard','Versorgung gegen befristeten Durchflug']];
export function prototypeLabPanel(){return `<details data-disclosure="prototype-lab"><summary>Neue Spielweisen ausprobieren · getrennte Testwelt</summary><p>Begrenzte Regelprototypen mit bereitgestellten Beispielressourcen. Kein Geld, Material, Schiff oder Fortschritt deines normalen Spielstands wird verändert. Diese Versuche sind noch keine freigegebenen dauerhaften Wirtschaftssysteme.</p><div class="btnrow">${cases.map(([kind,choice,label])=>`<button data-prototype="${kind}" data-choice="${choice}">${label}</button>`).join('')}</div><div id="prototypeResult" role="status"></div></details>`;}
export function prototypeClick(event,root){const button=event.target.closest('[data-prototype]');if(!button)return;const out=root.querySelector('#prototypeResult');out.textContent='Getrenntes Szenario wird berechnet …';socket.emit('prototypeRun',{kind:button.dataset.prototype,choice:button.dataset.choice},data=>{
 if(data.error){out.textContent=data.error;return;}const r=data.result;let h='<p>'+esc(data.notice)+'</p><p><b>'+esc(r.decision)+'</b></p>';
 if(r.contract)h+=`<p>Vertrag: 20 Wasser · ${r.contract.price.toFixed(1)} Cr je Einheit · ${r.contract.remaining} offen · ${r.contract.escrow.toFixed(1)} Cr noch gebunden.</p><p>Auftraggeber: ${fmt(r.before.cash)} → ${fmt(r.after.cash)} Cr. Gelieferter Bestand: ${r.before.water} → ${r.after.water} Wasser.</p><ul>${r.contract.contributions.map(c=>`<li>${esc(c.player)}: ${c.n} Wasser geliefert, ${fmt(c.paid)} Cr erhalten.</li>`).join('')}</ul>`;
 if(r.operation)h+=r.operation.error?'<p>'+esc(r.operation.error)+'</p>':`<p>Fünf Zyklen: ${r.before.ice-r.after.ice} Eis verbraucht, ${r.after.water-r.before.water} Wasser erzeugt; ${r.operation.power} Energie benötigt, ${r.operation.seconds} s nominelle Zykluszeit.</p>`;
 if(r.choice)h+='<p>Entscheidung: '+esc(r.choice)+'. '+(r.known?'Eine reale Eisquelle wurde aufgeklärt: '+esc(r.source):'10 vorhandene Barren geborgen; '+r.remainingWreck+' Barren im Fund verbleiben.')+'</p>';
 if(r.pact)h+=`<p>40 Wasser und 40 Nahrung abgegeben. Durchflug während der vereinbarten Stunde: ${r.passageDuring?'erlaubt':'gesperrt'}; nach Ablauf: ${r.passageAfterExpiry?'erlaubt':'gesperrt'}. Keine dauerhafte Freundschaft.</p>`;
 out.innerHTML=h;
});}
